add('''## Results excluded from live claims and remaining gaps

- Legacy `letter11_permuted` reversal and `legend_stability` top-20% retention tables are audit-only. The legacy provenance regression failed; do not reuse the near-zero six-of-six or old selection-risk conclusions. The fresh reversal does not automatically validate the legacy retention table.
- Direction-cosine CSVs and related README interpretations use, or may inherit, the withdrawn target-selected `h_a = where(y,h_pos,h_neg)` construction. They are retained with a withdrawal/provenance warning, not used as shared pre/post computation evidence. Fixed-order paired AURC remains usable.
- Clean matched numeric caches in the alphabet inventory cover Llama only. Mistral/Qwen require re-elicitation; tokenizer-collision diagnostics alone are not replacement numeric confidence results. No digit10 direct-extraction result is saved here.
- Figure 1’s locked single-item selection and single-item forward/reverse values remain pending in `main_fig.md`.
- Frozen comparisons use one dataset-supplied negative candidate per question and off-policy teacher forcing. A distractor sweep requires additional extraction. There is no independent confirmatory fold for the main frozen comparison; the separate cached single-look additivity table should not be confused with one.
- The log-ratio diagnostic lacks an alternate-form full distribution and a preregistered null/decision gate. A delayed-read-position mechanism is untested.
- The full Tinker run has seed 0 only. Additional seeds, answer generators, calibration draws, and a prespecified K-selection study remain absent from the local completed-result inventory.

## Compilation checks

The compiler checks six fresh reversal cells with exactly five saved falsifications, exact equality of the two K=1 conformal baselines, and consistency between the full-run Brier difference and its saved answer-gain statistic. Additional checks performed during this compilation verified all 32 full-run prediction groups against manifest counts, unique questions within each group, matching IDs and labels across arms, disjoint split IDs, and all eight test Brier values recomputed from saved predictions. All ten full-run conformal summaries were reconciled against the saved per-question sets for coverage, mean size, and empty/singleton/full rates. All Markdown file links resolved. Source tables retain their own fold and uncertainty definitions; no incompatible datasets or targets are pooled. Blank source fields remain missing. This checks the compilation, not the scientific validity of every original analysis.
''')

def status(p):
    s=p.as_posix()
    if 'direction_cosines' in s: return 'withdrawn/provenance review: target-selected geometry'
    if '/letter11_permuted/' in s or '/legend_stability/' in s: return 'legacy audit-only; superseded for live reversal claims'
    if 'demo_run' in s: return 'simulated software demonstration'
    if 'letter11_provenance_v1' in s: return 'fresh provenance-controlled reversal'
    if 'p2_iclr/' in s: return 'saved exploratory prose audit'
    if 'pilot_' in s or 'smoke_' in s: return 'pilot/smoke; not independent full replication'
    if 'evaluations_revisited/' in s or 'verbalized_confidence/' in s: return 'upstream evidence/input; not new local experiment'
    if '/data/' in s: return 'prepared input/provenance; not completed training'
    return 'saved result/provenance; interpret with report scope'

snapshot = {'as_of':'2026-09-14','scope':'local checkout; no remote job audit','csv_tables':{},'json_results':{}}
inventory=[]
appendix=['# Saved result tables\n\nSource precision is retained in the JSON snapshot. Display values are rounded. Legacy status applies to the entire marked source, regardless of its original wording. Missing values display as —. Per-item tables and tables above 300 rows are linked rather than expanded.']
roots=['cached_results','token_mode_mean','tinker_uq/runs','tinker_uq/demo_run','neutral_prior','p2_iclr','evaluations_revisited','verbalized_confidence','tinker_uq/data']
for dirname in roots:
    for p in sorted((ROOT/dirname).rglob('*')):
        if not p.is_file() or p.suffix not in {'.csv','.json','.jsonl','.md','.pdf','.png','.npz'}: continue
        rel=p.relative_to(ROOT); tag=status(rel); n=''
        # Do not copy prompts, raw answer corpora, or prediction/training streams.
        if p.suffix=='.csv' and dirname not in {'evaluations_revisited','verbalized_confidence'}:
            records=read_csv(rel); n=len(records)
            snapshot['csv_tables'][str(rel)]={'status':tag,'rows':records}
            appendix.append(f'\n## {rel}\n\nStatus: {tag}. Rows: {n}. Source: {link(rel)}.\n')
            if records and n<=300 and 'per_item' not in p.name and 'predictions' not in p.name:
                keys=list(records[0]); ids=[k for k in ['model','dataset','signal','seed','fold','variant','side','pooling','margin_bin','readout','metric','target','stratum'] if k in keys]
                vals=[k for k in keys if k not in ids]
                # Split wide tables into readable groups, retaining all columns.
                for i in range(0,len(vals),5):
                    cols=ids+vals[i:i+5]
                    appendix.append(table(cols,[[r.get(k,'') for k in cols] for r in records]))
            else:
                appendix.append('Detailed rows are available in the linked source and JSON snapshot.')
        elif p.suffix=='.json' and p.name not in {'prompt_audit.json','calibration.json'}:
            snapshot['json_results'][str(rel)]={'status':tag,'data':json.loads(p.read_text())}
        # Hash compact source evidence; avoid copying/hash-reading large raw streams.
        digest=hashlib.sha256(p.read_bytes()).hexdigest() if p.stat().st_size<5_000_000 else 'not hashed (large raw artifact)'
        inventory.append({'path':str(rel),'bytes':p.stat().st_size,'rows':n,'status':tag,'sha256':digest})

snapshot['sources']=inventory
(OUT/'RESULTS.md').write_text('\n\n'.join(parts)+'\n')
(OUT/'TABLES.md').write_text('\n\n'.join(appendix)+'\n')
(OUT/'results_snapshot.json').write_text(json.dumps(snapshot,indent=2,ensure_ascii=False)+'\n')
(OUT/'SOURCES.md').write_text('# Local source inventory\n\nAll artifacts below were present at compilation. Raw inputs, images, and streams are indexed without implying independent experiments. Source status is contextual; the report explains corrections. Prompt audits are indexed but not copied into the snapshot.\n\n'+table(['Source','Bytes','CSV rows','Status','SHA-256'],[[link(r['path']),r['bytes'],r['rows'],r['status'],r['sha256']] for r in inventory])+'\n')
print(f'Wrote report, table appendix, source inventory, and JSON snapshot in {OUT}')
print(f'{len(inventory)} source artifacts; {len(snapshot["csv_tables"])} CSV tables; {len(snapshot["json_results"])} result/provenance JSONs')
